// Works come from js/works.js (generated by tools/build.py from works.json).
const WORKS = window.WORKS;

// Prices: keep identical to PRICES in functions/api/order.js
const SIZES = [
  {id:"A4", label:"A4 · 21 × 29.7 cm", price:35},
  {id:"A3", label:"A3 · 29.7 × 42 cm", price:55},
  {id:"A2", label:"A2 · 42 × 59.4 cm", price:90},
];
const ORDER_ENDPOINT = "/api/order";

const $ = s => document.querySelector(s);
const eur = n => "€" + n;

// theme toggle (remembered per visitor)
const root = document.documentElement;
function currentTheme(){ return root.dataset.theme === "dark" ? "dark" : "light"; }   // light unless the visitor picks dark
function paintToggle(){ $("#theme").setAttribute("aria-checked", String(currentTheme()==="dark")); }
try{ const t = localStorage.getItem("theme"); if(t) root.dataset.theme = t; }catch(e){}
paintToggle();
$("#theme").addEventListener("click",()=>{
  root.dataset.theme = currentTheme()==="dark" ? "light" : "dark";
  try{ localStorage.setItem("theme", root.dataset.theme); }catch(e){}
  paintToggle();
});

// discourage casual saving: no right-click menu or dragging on the artwork
document.addEventListener("contextmenu", e=>{ if(e.target.closest(".piece img, #vImg")) e.preventDefault(); });
document.addEventListener("dragstart", e=>{ if(e.target.tagName==="IMG") e.preventDefault(); });

// wall
const wall = $("#wall");
const pieces = WORKS.map((w,i)=>{
  const b = document.createElement("button");
  b.className = "piece tone-" + w.tone; b.type = "button";
  b.innerHTML = `<img src="img/${w.id}-sm.webp" width="${w.w}" height="${w.h}" loading="${i<6?"eager":"lazy"}" alt="${w.title}, drawing by Senseless Zeal"><span class="cap"><b></b></span>`;
  b.querySelector("b").textContent = w.title;
  b.addEventListener("click",()=>openViewer(i));
  return b;
});

// Masonry that reads left to right: each work goes into the currently shortest column,
// so the order in works.json is the order you see across the top rows.
let lastCols = 0;
function layout(force){
  const gap = parseFloat(getComputedStyle(wall).columnGap) || 24;
  const n = Math.max(1, Math.min(3, Math.floor((wall.clientWidth + gap) / (300 + gap))));
  if(n === lastCols && !force) return;
  lastCols = n;
  const cols = Array.from({length:n}, ()=>{ const c=document.createElement("div"); c.className="col"; return c; });
  const heights = new Array(n).fill(0);
  visible.forEach(i=>{
    const k = heights.indexOf(Math.min(...heights));
    cols[k].appendChild(pieces[i]);
    heights[k] += WORKS[i].h / WORKS[i].w + 0.25;   // image ratio + caption/spacing
  });
  wall.replaceChildren(...cols);
}
addEventListener("resize", ()=>layout(false));

// tag filter
const TAGS = window.TAGS || [];
let visible = WORKS.map((_,i)=>i);   // indices of works currently shown; the viewer cycles through these
let activeTag = "";
const filters = $("#filters");
function filterButton(id,label,n){
  const b = document.createElement("button");
  b.type = "button"; b.dataset.tag = id;
  b.className = "tag";
  b.innerHTML = `<i class="hole" aria-hidden="true"></i><span></span><small></small>`;
  b.querySelector("span").textContent = label;
  b.querySelector("small").textContent = n;
  b.addEventListener("click",()=>setTag(id));
  filters.appendChild(b);
}
filterButton("", "All", WORKS.length);
// tags listed by how many works they hold, biggest first
TAGS.map(t=>({...t, n: WORKS.filter(w=>w.tags.includes(t.id)).length}))
  .filter(t=>t.n)
  .sort((a,b)=>b.n-a.n)
  .forEach(t=>filterButton(t.id, t.label, t.n));
function setTag(id){
  activeTag = TAGS.some(t=>t.id===id) ? id : "";
  visible = [];
  WORKS.forEach((w,i)=>{
    const on = !activeTag || w.tags.includes(activeTag);
    if(on) visible.push(i);
  });
  layout(true);
  filters.querySelectorAll("button").forEach(b=>b.setAttribute("aria-pressed", String(b.dataset.tag===activeTag)));
  const label = activeTag ? TAGS.find(t=>t.id===activeTag).label : "";
  $("#count").textContent = visible.length + (visible.length===1?" work":" works") + (label ? " in " + label : "");
  try{
    const u = new URL(location.href);
    activeTag ? u.searchParams.set("tag",activeTag) : u.searchParams.delete("tag");
    history.replaceState(null,"",u);
  }catch(e){}
}
let startTag = "";
try{ startTag = new URL(location.href).searchParams.get("tag") || ""; }catch(e){}
setTag(startTag);

// prices list
$("#prices").innerHTML = SIZES.map(s=>`<div><span>${s.label}</span><span>${eur(s.price)}</span></div>`).join("");

// viewer
let cur = 0, lastFocus = null;
const viewer = $("#viewer");
function show(i){
  cur = i;
  const w = WORKS[cur];
  $("#vImg").src = `img/${w.id}.webp`;
  $("#vImg").className = "tone-" + w.tone;
  $("#vImg").alt = w.title + ", drawing by Senseless Zeal";
  $("#vIndex").textContent = (visible.indexOf(cur)+1) + " / " + visible.length;
  $("#vTitle").textContent = w.title;
  $("#vMedium").textContent = w.medium;
  $("#vFrom").textContent = "Prints from " + eur(SIZES[0].price) + ". Originals on request.";
}
// step through the works currently visible under the active filter
function step(d){ const k = visible.indexOf(cur); show(visible[(k + d + visible.length) % visible.length]); }
function openViewer(i){ lastFocus = document.activeElement; show(i); viewer.hidden = false; document.body.style.overflow="hidden"; $("#vClose").focus(); }
function closeViewer(){ viewer.hidden = true; document.body.style.overflow=""; lastFocus && lastFocus.focus(); }
$("#vPrev").onclick = ()=>step(-1);
$("#vNext").onclick = ()=>step(1);
$("#vClose").onclick = closeViewer;
$("#vImg").onclick = closeViewer;
$("#vOrder").onclick = ()=>{ $("#piece").value = WORKS[cur].id; updateTotal(); closeViewer(); $("#order").scrollIntoView(); setTimeout(()=>$("#name").focus({preventScroll:true}),400); };
document.addEventListener("keydown",e=>{
  if(viewer.hidden) return;
  if(e.key==="Escape") closeViewer();
  if(e.key==="ArrowRight") step(1);
  if(e.key==="ArrowLeft") step(-1);
});
let tx=null;
viewer.addEventListener("touchstart",e=>{tx=e.touches[0].clientX},{passive:true});
viewer.addEventListener("touchend",e=>{ if(tx===null) return; const d=e.changedTouches[0].clientX-tx; if(Math.abs(d)>50) step(d<0?1:-1); tx=null; });

// order form
$("#piece").innerHTML = WORKS.map((w,i)=>`<option value="${w.id}">${w.title}</option>`).join("");
$("#sizes").innerHTML = SIZES.map((s,i)=>`<label><input type="radio" name="size" value="${s.id}" ${i===0?"checked":""}><span><b>${s.id}</b>${eur(s.price)}</span></label>`).join("");
function order(){
  const f = $("#form");
  const size = SIZES.find(s=>s.id===f.size.value) || SIZES[0];
  const qty = Math.min(10, Math.max(1, parseInt(f.qty.value,10) || 1));
  const w = WORKS.find(x=>x.id===f.piece.value);
  return {piece:w.id, title:w.title, size:size.id, unitPrice:size.price, qty, total:size.price*qty,
          name:f.name.value.trim(), email:f.email.value.trim(), country:f.country.value.trim(),
          note:f.note.value.trim(), original:f.original.checked};
}
function stepQty(d){ const q=$("#qty"); q.value = Math.min(10, Math.max(1, (parseInt(q.value,10)||1) + d)); updateTotal(); }
$("#qtyDown").onclick = ()=>stepQty(-1);
$("#qtyUp").onclick = ()=>stepQty(1);
function updateTotal(){ $("#total").textContent = eur(order().total); }
$("#form").addEventListener("input", updateTotal);
updateTotal();

$("#form").addEventListener("submit", async e=>{
  e.preventDefault();
  const o = order(), err = $("#err");
  const bad = !o.name ? "Add your name." : !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(o.email) ? "Add a valid email so the payment link can reach you." : !o.country ? "Add the country the print ships to." : "";
  if(bad){ err.textContent = bad; err.hidden = false; return; }
  err.hidden = true;
  const btn = $("#submit"); btn.disabled = true; btn.textContent = "Sending…";
  let sent = false;
  try{
    const r = await fetch(ORDER_ENDPOINT,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(o)});
    if(r.ok) sent = true;
    else if(r.status !== 404 && r.status !== 405){ throw new Error("server"); }
  }catch(ex){
    if(ex.message==="server"){ err.textContent = "The order didn't go through. Check your connection and try again."; err.hidden=false; btn.disabled=false; btn.textContent="Place order"; return; }
  }
  const box = $("#orderBox");
  box.innerHTML = `<div class="done" role="status"><h3>Thank you.</h3><p></p><p>Check your inbox for the confirmation email with the payment link. Your print goes into production once payment is complete.</p><p class="note" ${sent?"hidden":""}>Preview: ordering goes live once the site is deployed, so this order was not sent.</p><button class="btn ghost" type="button" id="again">Order another print</button></div>`;
  box.querySelector("p").textContent = `${o.qty} × ${o.title}, ${o.size} — ${eur(o.total)}.` + (sent ? ` Confirmation sent to ${o.email}.` : "");
  $("#again").onclick = ()=>location.reload();
});
